        UNION { VALUES ?root { wd:Q3889188 wd:Q2095069 wd:Q726210 wd:Q28911163 wd:Q13770084 wd:Q7066678 wd:Q1756295 wd:Q1933581 wd:Q7068969 wd:Q113573759 wd:Q109490960 wd:Q109490472 wd:Q122331539 wd:Q121451784 wd:Q109610894 wd:Q109610857 wd:Q121451586 wd:Q2279584 wd:Q10388960 wd:Q124355768 } ?item wdt:P279 ?root }
